<?php
declare(strict_types=1);
require_once __DIR__.'/libs/world-map.inc.php';
$uid=alphano_require_login();$db=ConnectDB();
$area=filter_var($_GET['area']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);if($area===false)alphano_fail('Luogo non valido.',422);
$selected=$area?$db->query('SELECT * FROM world_areas WHERE id=? AND enabled=1',[$area])[0]??null:null;if($area&&!$selected)alphano_fail('Luogo non trovato.',404);
$db->execute("UPDATE utenti SET posizione='online',chat='',lastmove=? WHERE id=?",[time(),$uid]);
$rows=alphano_world_map_rows((int)$area);$mapConfig=alphano_world_map();$view=in_array($_GET['view']??'', ['cards','visual'],true)?$_GET['view']:$mapConfig['mode'];$mapPayload=alphano_world_map_payload((int)$area,$rows);$visual=$view==='visual'&&$mapPayload['image']!=='';

?>
<!doctype html><html lang="it"><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/atlas.css"><script src="/assets/atlas.js" defer></script><title><?=alphano_escape($selected['title']??'Esplora il mondo')?> · <?=alphano_escape(TitoloSito)?></title></head><body class="world <?=$visual?'world-visual':''?>" <?=$visual?'data-ui-workspace':''?>><main class="world-wrap"><?php if($visual):alphano_world_map_component($mapPayload,$selected['title']??'Mappa del mondo',$selected?'/mappa.php':'/mappa.php?view=cards');else:?><header data-page-heading><p class="eyebrow"><?=alphano_escape(TitoloSito)?> · Esplora</p><?php if($selected):?><a href="/mappa.php">← Tutte le città e i territori</a><?php endif;?><h1><?=alphano_escape($selected['title']??'Scegli la tua destinazione')?></h1><p class="muted"><?=alphano_escape($selected['description']??'Città, territori e luoghi di incontro. Ogni scheda apre le chat della destinazione.')?></p></header><?php if($view==='visual'):?><p class="notice">Lo sfondo di questa mappa non è ancora impostato. Puoi esplorare le destinazioni dall’elenco.</p><?php endif;?><nav class="atlas-view-switch"><a href="?<?=http_build_query(['area'=>$area,'view'=>'cards'])?>">Vista a card</a> · <a href="?<?=http_build_query(['area'=>$area,'view'=>'visual'])?>">Mappa visiva</a></nav><div class="world-grid"><?php foreach($rows as $row):$url=$selected?'/chat/index.php?chat='.rawurlencode($row['chat_key']):'/mappa.php?area='.(int)$row['id'];$image=alphano_world_image((string)($selected?($row['scene_thumbnail']?:$row['scene_image']):$row['image']));?><a class="world-card" href="<?=alphano_escape($url)?>"><img loading="lazy" src="<?=alphano_escape($image)?>" alt="<?=alphano_escape($row['title'])?>"><div class="card-copy"><h2><?=alphano_escape($row['title'])?></h2><p><?=nl2br(alphano_escape($selected?$row['descrizione']:$row['description']))?></p><small><?=$selected?'Entra in chat →':(int)$row['rooms'].' luoghi · Esplora →'?></small></div></a><?php endforeach;?></div><?php if(!$rows):?><p>Nessun luogo disponibile. Lo staff può aggiungerlo dalla gestione del mondo.</p><?php endif;?><?php endif;?><?php if(!$visual):?><nav class="atlas-bottom"><a href="?<?=http_build_query(['area'=>$area,'view'=>$visual?'cards':'visual'])?>"><?=$visual?'Vista a card':'Mappa visiva'?></a> · <a href="/bacheche/">Bacheche</a><?php if(alphano_can('admin')):?> · <a href="/admin/world.php">Gestisci città e chat</a><?php endif;?></nav><?php endif;?></main></body></html>
